import{_ as p,c as e,o as r,af as t}from"./chunks/framework.4G89wRmb.js";const d=JSON.parse('{"title":"5.1 南武公学会叙","description":"","frontmatter":{"title":"5.1 南武公学会叙"},"headers":[],"relativePath":"archives_n_arts/arts/nambu_blue/5.1.md","filePath":"archives_n_arts/arts/nambu_blue/5.1.md"}'),n={name:"archives_n_arts/arts/nambu_blue/5.1.md"};function s(_,a,i,l,o,h){return r(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="五" tabindex="-1">五 <a class="header-anchor" href="#五" aria-label="Permalink to “五”">​</a></h1><h2 id="_1-南武公学会叙" tabindex="-1">1. 南武公学会叙 <a class="header-anchor" href="#_1-南武公学会叙" aria-label="Permalink to “1. 南武公学会叙”">​</a></h2><p>黄节</p><h3 id="中文版" tabindex="-1">中文版 <a class="header-anchor" href="#中文版" aria-label="Permalink to “中文版”">​</a></h3><p>五岭以南，南武一大都会，攻其所自，实始自粤人公师隅，河山如旧，已非吾土。嗟乎！今犹有汉明之遗物存者，则议郎之邦，郭家之鹰爪花而已！</p><p>乙春（光绪三一年），同人治地于海幢寺侧，为公学一大区，览草木之繁殖，绎夫西哲生物竞争之论，则皇然以惧，悠然以思，然以鸣曰：学者殖也，不殖将落！吾四千里无学，种安有不衰且灭者乎！</p><p>自孔子以后，汉宋经师，开门讲学，以迄有明，号称极盛，而于群治之进退，则无丝毫影响。</p><p>何者？学在一二贤达，而未尝普于吾民。盖不独吾粤为已然矣。</p><p>闪子之言曰：“大人者，患失而感，曰可以无学，无学不害，不害而不学，则苟而可。”坐此说也，吾群遂四千年无学！</p><p>夫至于害而学焉，不已晚乎，海通以来，泰西民族主义，日以东渐，以吾不学之旧族，以当欧美文明国民，则事事大，既知无学之为害也，大人者则曰：“与学矣！与学矣！”</p><p>然而学校偏于行省，而于群治之进退，则亦无丝毫影响。何者？学在官则新旧有争，公私有争，而未尝普于吾民，盖不独吾粤为已然矣。</p><p>同人是学会为： 图书一部，智者一部，体育一部，翻译一部。</p><p>将聚吾族而学焉，则又皇然以惧，悠然以思，益焉以鸣曰：“吾学固公而非官者也，凡吾同人毋为败群以贻吾族羞！”</p><p>箐义之序曰：箐箐者义，乐育材也。若弃义之根而泽其叶，加之异类而同育焉，天下将优义之不箐箐矣。</p><p>仰又闻之，伐木之序曰：“自天子至于庶人，未有不须友以成者。”故笺曰，“和平斋等也”。</p><p>同人丁嘤求友，倘亦有闻声而应者乎，则不话中原采菽之思矣！</p><h3 id="日文版" tabindex="-1">日文版 <a class="header-anchor" href="#日文版" aria-label="Permalink to “日文版”">​</a></h3><p>五嶺以南、南武一大都會、其の自る所を攻む、實に粵人公師隅より始まる、河山舊の如きも、已に吾が土に非ず。嗟乎、今猶ほ漢明の遺物存する者有らば、則ち議郎の邦、郭家の鷹爪花のみ。</p><p>乙春（光緒三一年）、同人地を海幢寺の側に治め、公學の一大區と為す、草木の繁殖を覽、夫の西哲生物競爭の論を繹ぬるに、則ち皇然として以て懼れ、悠然として以て思ひ、然として以て鳴きて曰はく、學は殖なり、殖えざれば將に落ちんとす、吾が四千里學無くんば、種安んぞ衰へ且つ滅せざる者有らんや、と。</p><p>孔子以後、漢宋の經師、門を開きて學を講じ、以て有明に迄る、號して極盛と稱すと雖も、而して群治の進退に於ては、則ち絲毫の影響無し。</p><p>何者ぞ。學は一二の賢達に在りて、未だ嘗て吾が民に普からず。蓋し獨り吾が粵のみ已然と為すに非ざるなり。</p><p>閃子の言に曰はく、大人なる者、失ふを患へて感じ、曰はく以て學無かる可し、學無きも害せず、害せずして學ばざれば、則ち苟くして可なり、と。此の說に坐するや、吾が群遂に四千年學無し。</p><p>夫れ害に至りて學ばば、已に晚からずや。海通以來、泰西民族主義、日に以て東漸す、吾が不學の舊族を以て、以て歐美文明の國民に當らば、則ち事事大なり。既に無學の害爲ることを知るや、大人なる者則ち曰はく、學を與へよ、學を與へよ、と。</p><p>然れども學校行省に偏し、而して群治の進退に於ては、則ち亦た絲毫の影響無し。何者ぞ。學官に在れば則ち新舊爭ひ有り、公私爭ひ有り、而して未だ嘗て吾が民に普からず。蓋し獨り吾が粵のみ已然と為すに非ざるなり。</p><p>同人是の學會を爲す、 圖書一部、智者一部、體育一部、翻譯一部。</p><p>將に吾が族を聚めて學ばしめんとするに、則ち又た皇然として以て懼れ、悠然として以て思ひ、益々焉として以て鳴きて曰はく、吾が學固より公にして官に非ざる者なり、凡そ吾が同人群を敗りて以て吾が族の羞を貽すこと毋かれ、と。</p><p>菁義の序に曰はく、菁菁たる者は義なり、材を育するを樂しむなり。若し義の根を棄てて其の葉を澤し、之に異類を加へて同に育せしめば、天下將に義の菁菁たらざるを憂へんとす、と。</p><p>仰いで又た之を聞く、伐木の序に曰はく、天子自り庶人に至るまで、未だ友を須ちて以て成さざる者有らず、と。故に箋に曰はく、和平齊等なり、と。</p><p>同人丁嘤として友を求む、倘し亦た聲を聞きて應ずる者有らんか、則ち中原采菽の思ひを話はざらんや。</p>',29)])])}const m=p(n,[["render",s]]);export{d as __pageData,m as default};
